  'about.bookshopLeadIn': "私たちの書店を営むのと同じ小さな事業者によって作られました:",
  "about.eyebrow": "Luminous StockHavenについて",
  "about.pageTitle": "Luminous StockHaven — 会社概要",
  "about.founderHeading": "📖 創設者について",
  "about.founder.p1": "こんにちは、Luminous StockHavenの創設者、コンセプシオンです。",
  "about.founder.p2": "私は大手テクノロジー企業の出身ではなく、企業のオフィスに座っているわけでもありません。私は皆さんと同じ、小さな小売店のオーナーです。本と、本好きのための手作りアクセサリーを専門とする5つのオンラインストアを運営しています。\n多くの独立系小売業者と同じように、複数の拠点の在庫管理、出版社のISBNと自作のSKUの並行管理、そして扱いにくいスプレッドシートでの仕入先への発注に限界を感じていました。助けになるアプリを探して、6つの選択肢を試しました。どれも完全に不完全か、信じられないほど分かりにくいか、あるいは法外で、基本的なツールに月額数百ドルを請求していました。",
  "about.founder.p3": "独立したクリエイターを搾取する業界に苛立ちを覚え、自分自身の解決策を作ることに決めました。Luminous StockHavenは、自分のビジネスを清潔に、効率的に、そして完全な安心感をもって運営する必要性から生まれました。",
  "about.founder.p4": "すべての小さな店舗オーナーが、収益を危険にさらすことなく本当に役立つツールに値するからこそ、このプラットフォームを正直で手頃な価格で一般公開することにしました。私たちは独立所有であり、コミュニティを断固として守り、小売業者によって小売業者のために作られました。",
  "notice.ariaLabel": "商標および著作権に関する通知",
  "notice.heading": "🛡️ 小売業者のために作られ、企業のハゲタカには値段がつけられない",
  "notice.intro": "このアプリを作ったのは、私が5つの店舗を運営していて、数百ドルの分かりにくいソフトウェアに騙され続けることにうんざりしていたからです。このアプリは、独立したアーティスト、職人、書店員、地元の店舗を守るために作られました。",
  "notice.legalHeading": "競合他社および模倣者への法的通知：",
