  "plans.priceNote": "Essentials は月額 $14.99 に適用される税金（ある場合）が加算されます。Business は月額 $29.99 に適用される税金（ある場合）が加算されます。必要な税金はプロバイダーのチェックアウト時に決まり、支払い前に最終合計に表示される必要があります。この比較ページは税金の見積もりでも支払いの承認でもありません。",
