  "upgrade.chargedThroughProviderNote": "プランの変更は請求プロバイダーを通じて請求されます。サブスクリプションは、現在のプランの下にある「サブスクリプションをキャンセル」ボタンを使ってこのページから、または設定からキャンセルできます。キャンセルすると、有料期間の終了時に今後の更新が停止します。アクセスが即座に終了することはありません。既存の無料ワークスペースは、これらのオプションを表示しただけでは請求されません。",
  "billing.cancel.title": "サブスクリプションをキャンセルする",
  "billing.cancel.description": "{plan} の登録を解除します。キャンセルすると、有料期間の終了時に今後の更新が停止します — アクセスが即座に終了することはありません。",
  "billing.cancel.yourPlan": "あなたのプラン",
  "billing.cancel.doneTitle": "サブスクリプションがキャンセルされました。",
  "billing.cancel.doneWithEnd": "{endDate} まではフルアクセスを維持できます。その日以降は {graceDays} 日間の読み取り専用の猶予期間があります — ログインして商品を見ることはできますが、追加、編集、削除、スキャン、インポート、エクスポート、変更はできません。{gracePart}",
  "billing.cancel.graceEndsOn": "15日間の猶予期間が {date} に終了した後、アカウントとすべての情報は完全に削除され、復元できません。",
  "billing.cancel.doneNoEnd": "有料期間の終了まではフルアクセスを維持できます。その後、15日間の読み取り専用の猶予期間が適用されます。{wipeSentence}",
  "billing.cancel.refundWindowOpen": "最初の有料請求から3日以内にキャンセルしたため、その最初の支払いの返金対象となる場合があります。キャンセル自体で返金が行われるわけではありません — {contact} を通じてリクエストしてください。",
  "billing.cancel.refundWindowClosed": "キャンセル自体で返金が行われるわけではありません。返金は、最初の有料請求の成功から3日以内に、{contact} を通じてリクエストされた場合にのみ適用されます。",
  "billing.cancel.notCanceledTitle": "サブスクリプションはキャンセルされませんでした。",
  "billing.cancel.contactCode": "{contact} にお問い合わせの際は、このコードをお伝えください：{code}",
  "billing.cancel.alreadyCanceledTitle": "このサブスクリプションはすでにキャンセルされています。",
  "billing.cancel.alreadyCanceledWithEnd": "{date} に終了します。それまではフルアクセスを維持できます。その日以降は、商品を見るための {graceDays} 日間の読み取り専用の猶予期間があります。{wipeSentence}",
  "billing.cancel.alreadyCanceledNoEnd": "現在の有料期間の終了時に終了します。それまではフルアクセスを維持できます。",
  "billing.cancel.appStoreNote": "Google Play または Apple App Store を通じて登録したことがある場合は、そのストアのサブスクリプション設定からキャンセルする必要がある場合があります。このダイアログではアプリストアの請求を停止できません。アプリをアンインストールしたり、StockHaven アカウントを削除したりしても、ストアのサブスクリプションはキャンセルされません。",
  "billing.cancel.trialNote": "トライアル中にキャンセルしても、7日間はすべて使えます — アクセスは {date} に終了し、請求は行われません。",
  "billing.cancel.trialNoteNoDate": "トライアル中にキャンセルしても、7日間はすべて使え、請求は行われません。",
  "billing.cancel.keepAccessUntil": "{date} まではフルアクセスを維持できます。",
  "billing.cancel.endOfPaidPeriod": "有料期間の終了時",
  "billing.cancel.keepAccessRest": "キャンセルすると今後の更新が停止するだけです — アクセスが即座に終了することはなく、無料期間が追加されることもありません。",
  "billing.cancel.gracePeriodTitle": "その日以降、{graceDays} 日間の読み取り専用の猶予期間があります。",
  "billing.cancel.gracePeriodRest": "ログインして商品を見ることができるため、持っていたものを眺めて書き留めることができます。それ以外はすべてブロックされます：追加、編集、削除、スキャン、インポート、エクスポート、移行はできず、設定もスタッフも使えません。",
  "billing.cancel.resubscribeFresh": "再登録は最初から始まります。",
