  "settings.delete.intro": "リクエストを送信しても、アカウント、ビジネス、在庫が即座に削除されることはありません。リクエストは、削除が完了する前に別途レビューされます。このリクエストでは Stripe サブスクリプションはキャンセルされず、今後の請求も停止しません。サブスクリプションのキャンセルは、請求プロバイダーを通じて別途処理する必要があります。",
