  "payroll.dd.savings": "貯蓄預金",
  "payroll.dd.steps.body": "1. ACH送金ができる事業用銀行口座が必要です。2. 各チームメンバーから署名入りの承認フォームを受け取ってください — 無効の小切手があると番号の確認に役立ちます。3. 給料日の2〜3営業日前に給与を送金すると、お金が期日に届きます。4. ほとんどの州ではチームメンバーの書面による同意が必要です。このアプリはフォームを集め、手順をご案内します — 実際のお金の送金はご自分の銀行を通じて行います。",
