  "plansLib.includes.support": "アプリ内の問題報告",
  "support.category.broken": "何かが壊れています",
  "support.category.idea": "アイデアまたは提案",
  "support.category.looksWrong": "何かが間違って見えます",
  "support.category.other": "その他",
  "support.categoryLabel": "これは何についてですか？",
  "support.contextNote": "問題を見つけられるよう、あなたのメモには、あなたがいるページ、選択されている場合はあなたのビジネスと役割、プラン、アプリの言語、使用しているスマートフォンやブラウザの種類が自動的に含まれます。商品、在庫、売上は決して含まれません。",
  "support.description": "何か壊れている、何か間違って見える、または共有したいアイデアがありますか？ここで教えてください — あなたのメモはアプリの開発チームに直接届きます。",
  "support.errorGeneric": "送信できませんでした。もう一度お試しください。",
  "support.errorRateLimit": "今日すでにいくつかの報告を送信しています — ありがとうございます。すべての報告をきちんと読めるよう、明日まで待ってからさらに送信してください。",
  "support.errorTooLong": "それは報告に収まる長さを超えています — 少し短くして、もう一度送信してください。",
  "support.errorTooShort": "もう少し詳しく教えてください — 1〜2文あると見つけやすくなります。",
  "support.messageLabel": "何が起きましたか？",
  "support.messagePlaceholder": "あなたが何をしていて、何がうまくいかなかったかを、自分の言葉で教えてください…",
  "support.sendAnother": "別の報告を送信する",
  "support.sending": "送信しています…",
  "support.sentBody": "すべての報告を読みます。さらに詳しく必要な場合は、あなたのアカウントのメールアドレスに連絡します。",
  "support.sentTitle": "ありがとうございます — 報告が送信されました。",
  "support.submit": "報告を送信する",
  "support.title": "問題を報告する",
  "support.urgentNote": "代わりにアカウントから締め出されましたか？予備の鍵で戻ることができます — 上のセキュリティと予備の鍵を参照するか、サインイン画面の復旧口を使ってください。",
  "training.lessons.mgr-report-problem.step1": "あなたのチームはレジで働いており、問題が最初に現れるのはそこです。アプリが壊れたり、チームの誰かにとって奇妙な動作をしたりした場合は、その場で報告できます — 本人でもあなたでも — 設定の「問題を報告する」からです。",
  "training.lessons.mgr-report-problem.step2": "分かりやすい話をお願いしてください：何をしていたか、何を想定していたか、代わりに何が起きたかです。その1〜2文は、後で書かれた完璧な説明よりも価値があります。",
  "training.lessons.mgr-report-problem.step3": "報告には、ページ、店舗、送信者の役割、プラン、アプリの言語、デバイスの種類が自動で添付されます。商品、在庫、売上は決して添付されません。店舗の数字に関するものが報告とともに外に出ることはありません。",
  "training.lessons.mgr-report-problem.step4": "報告はアプリの開発チームに届き、すべて読まれます。問題で誰かがアカウントから締め出されている場合は、報告を待たないでください：予備の鍵とサインイン画面の復旧口で戻ることができます。",
  "training.lessons.mgr-report-problem.title": "チームが問題にぶつかったとき：回避せずに報告してください",
  "training.lessons.owner-report-problem.step1": "あなたのサブスクリプションには、このアプリを作る人々への直通回線が含まれます。設定を開いて「問題を報告する」を使ってください — すべてのプランにあり、あなたとチームのすべてのメンバーが使えます。",
  "training.lessons.owner-report-problem.step2": "自分の言葉で何が起きたかを伝えてください：何をしようとしていたか、代わりにアプリが何をしたかです。フォームは修正に役立つ詳細 — ページ、ビジネス、役割、プラン、言語、デバイス — を自動で添付します。商品、在庫、売上は決して含まれません。",
  "training.lessons.owner-report-problem.step3": "すべての報告は保存され、チームが読みます。さらに詳しく必要な場合は、送信した人のアカウントのメールアドレスに返信します — そのため、回答は問題を見た人に届きます。",
  "training.lessons.owner-report-problem.step4": "1つの例外：あなたまたはチームメンバーがアカウントにまったく入ることができない場合、報告は最速の扉ではありません。予備の鍵（設定、セキュリティと予備の鍵）とサインイン画面の復旧口は、まさにそのためにあります。",
  "training.lessons.owner-report-problem.title": "問題を報告する：アプリチームへの直通回線",
  "training.lessons.report-problem.step1": "アプリの何かが壊れたり、間違って見えたり、単に違和感がある場合、我慢する必要はありません。設定を開いて「問題を報告する」を見つけてください — すべてのプランで、すべての人が使えます。",
  "training.lessons.report-problem.step2": "メモの内容を選んでください — 何かが壊れている、何かが間違って見える、アイデア、その他 — 次に、何が起きたかを自分の言葉で書いてください。そのときに何をしていたかが最も役立ちます。",
  "training.lessons.report-problem.step3": "あなたのメモには、あなたがいたページ、店舗と役割、プラン、アプリの言語、使用しているスマートフォンやブラウザの種類が自動で含まれます — 問題を見つけるのに役立つ詳細です。商品、在庫、売上は決して含まれません。",
  "training.lessons.report-problem.step4": "送信すると、アプリの開発チームに直接届き、すべての報告が読まれます。さらに詳しく必要な場合は、あなたのアカウントのメールアドレスに連絡します。代わりにアカウントから締め出されましたか？予備の鍵またはサインイン画面の復旧口を使ってください — そちらの方が報告より速いです。",
  "training.lessons.report-problem.title": "問題を報告する：何か壊れたら教えてください",
  "crossStore.transferButton": "在庫を移動",
  "crossStore.transferChooseProduct": "製品を選んでください…",
  "crossStore.transferFailed": "その移動は完了しませんでした。",
