  "crossStore.transferIntro": "どちらの店舗もあなたのものですので、リクエストなしで在庫を直接移動できます。製品を選び、数量と移動元の場所を指定し、移動先の店舗を選んでください。両方の店舗がすぐに更新され、両方に移動の記録が残ります。",
  "crossStore.transferNoTargets": "まだ他にあなたの店舗がありません。在庫は、あなたが所有する店舗の間でのみ移動できます。",
  "crossStore.transferOnHand": "在庫 {count} 件",
