  "crossStore.transferQuantity": "数量",
  "crossStore.transferSuccess": "{quantity} × {product} を {store} に移動しました。",
  "crossStore.transferTarget": "移動先",
  "crossStore.transferTitle": "別の店舗へ在庫を移動",
  "crossStore.transferToFirstLocation": "その最初の場所",
  "crossStore.transferToLocation": "移動先の場所",
  "training.lessons.owner-move-stock.step1": "リクエストは頼むためのもの、移動はオーナーの仕事です。店舗間受信箱のページにある「在庫を移動」パネルでは、オーナーであるあなたが、この店舗からあなたが所有する別の店舗へ、リクエストも待ち時間もなしに在庫を直接送れます。",
  "training.lessons.owner-move-stock.step2": "製品、それが出発する場所、数量を選んでください。アプリはその場所に何件あるかを表示し、一度の移動でそれを超えることは決してありません。",
  "training.lessons.owner-move-stock.step3": "移動先の店舗を選び、必要ならそこの正確な場所も選んでください。その店舗にすでに同じSKUがある場合、在庫はその製品に加わります。ない場合は、製品が在庫と一緒にコピーされます。",
  "training.lessons.owner-move-stock.step4": "両方の店舗に記録が残ります。この店舗には転出の記録が、もう一方には受け取りの記録が残ります。在庫が足りない、または相手の店舗があなたのものではないなど、移動できない場合は何も移動せず、アプリが理由を表示します。",
  "training.lessons.owner-move-stock.title": "自分の店舗間で在庫を移動する（Businessプラン）",
