  "pricing.sectionTitle": "販売価格",
  "pricing.startLabel": "開始",
  "training.lessons.mgr-pricing.step1": "Businessでは、製品フォームに「販売価格」セクションがあります。クリアランスは永久的な値下げで、設定すればそのまま続きます。ロールバックは日付のあるセールです。ロールバック価格、開始日、終了日を設定します。",
  "training.lessons.mgr-pricing.step2": "通常価格を再入力することは決してありません。製品に残り、製品リストとスキャナーでセール価格の横に表示されるので、誰でもその商品の普段の価格がわかります。",
  "training.lessons.mgr-pricing.step3": "ロールバックが始まったら新しい価格ラベルを印刷してください。ラベルには、その日に顧客が支払う価格が印刷されます。終了日を過ぎると価格は自動的に通常に戻ります。棚を整えるときに通常ラベルを印刷し直してください。",
  "training.lessons.mgr-pricing.step4": "「販売価格」セクションがロックされて表示される場合、そのビジネスはBusinessプランではありません。販売価格はそのプランの機能で、プランを変更できるのはオーナーだけです。",
  "training.lessons.mgr-pricing.title": "セールを実施する：クリアランスとロールバック",
  "training.lessons.owner-pricing.step1": "製品フォームの「販売価格」には2種類の値下げがあります。クリアランスは永久的です。クリアランス価格を設定すると、戻すまで下がったままです。ロールバックは一時的なセールで、開始日と終了日のある低い価格です。大きなお店でおなじみのセールと同じです。",
  "training.lessons.owner-pricing.step2": "通常価格が消えることは決してありません。ロールバック中、アプリはセール価格とその横に通常価格を表示し、印刷ラベルにはセール価格が載るので、棚とレジが一致します。",
  "training.lessons.owner-pricing.step3": "終了日を過ぎると、価格は自動的に通常価格に戻ります。覚えることも、元に戻す作業もいりません。まだ始まっていないロールバックは、製品リストに開始日が表示されます。",
  "training.lessons.owner-pricing.step4": "販売価格はBusinessプランの機能です。Essentialsではフィールドはロックされたままで、ビジネスがEssentialsに下がって戻ってきても、クリアランスとロールバックの設定は残したときのまま残っています。",
  "training.lessons.owner-pricing.title": "クリアランスとロールバック価格（Businessプラン）",
