  "print.carrier.title": "配送業者のラベル",
  "print.carrier.desc": "郵便料金は、これまで通り配送業者から購入してください — このアプリが郵便料金を販売することは決してありません。ですから、あなたが支払うのは常に配送業者自身の価格です。ラベルファイルをここに保存すれば、その注文に永久に残ります：あなたの記録として、何かあったときのために手元にあります。",
