  "print.style.title": "ドキュメントのスタイル",
  "print.style.desc": "ドキュメントをあなたのものにしましょう。これらの選択は、請求書、領収書、梱包明細、返品ドキュメント、製品シート、在庫カウントシート、ピッキングリストを彩り、あなたのビジネスのために記憶されます。",
