  "print.style.imageWidth": "画像の幅",
  "print.style.imageLength": "画像の長さ",
  "print.style.imageSizeHint": "幅はページ幅に対して画像が占める割合、長さは印刷できる最大の高さです。通常のサイズにするには欄を空のままにしてください。",
  "print.printedAt": "{date} {time} に印刷",
  "print.style.previewText": "素早い茶色のキツネが怠け者の犬を跳び越えます。1234567890",
  "training.lessons.owner-shipping-labels.step1": "印刷センターには両プランとも「配送ラベル」スタイルがあります。顧客の注文を選ぶと、購入者の名前と住所、差出人としてのあなたのビジネスが入った 4×6 ラベルを印刷できます。",
  "training.lessons.owner-shipping-labels.step2": "このラベルは、すべての顧客向け書類と同じくホワイトラベルです。載るのはあなたのビジネス名だけ——このアプリの名前は決して載りません——ので、あなたの店からの荷物はあなたの店から来たように見えます。",
  "training.lessons.owner-shipping-labels.step3": "お客様の住所は、最後の注文から90日間、その注文と一緒に保持されます。ラベルは、注文に保存された住所がある場合、そこから始まります。一度きりのラベルのために印刷時に入力した住所は保存されません。名前は注文から入力されるので、ラベルは書類と一致します。",
  "training.lessons.owner-shipping-labels.step4": "このラベルは、すべてのラベルと同じ4つの接続——Bluetooth、Wi-Fi、イーサネット、USB——で印刷でき、4×6 サーマルプリンターが標準サイズです。",
  "training.lessons.owner-shipping-labels.step5": "代わりに配送業者から郵便料金を購入しましたか？同じセクションで、配送業者のラベルファイル — PDF、PNG、JPG — をアップロードでき、その注文に永久に保存されます：あなたの記録として、何かあったときのために手元にあります。実際の4×6サイズで印刷されます。このアプリが郵便料金を販売することは決してありません。ですから配送業者の価格が唯一の価格であり、常​​に正しい価格です。",
  "training.lessons.owner-shipping-labels.title": "顧客注文用の配送ラベル",
  "training.lessons.print-shipping-label.step1": "注文の発送準備ができたら、印刷センターを開いて「配送ラベル」スタイルを選び、顧客の注文を選択します。購入者の名前は注文から自動で入ります。",
  "training.lessons.print-shipping-label.step2": "小包が送られる住所を確認してください。注文にお客様の住所がある場合 — 最後の注文から90日間保持されます — それが入力されます。印刷時に入力した住所は保存されないので、印刷する前に郵便番号と最後の行を注意深く確認してください。",
  "training.lessons.print-shipping-label.step3": "あなたのビジネスの名前が差出人として上部に印刷されます。住所もラベルに入れたい場合は差出人住所欄に入力してください。表示したくない場合は空欄のままにします。",
  "training.lessons.print-shipping-label.step4": "4×6 ラベルに印刷します。通常はサーマルラベルプリンターが適していますが、ブラウザの印刷ボタンからどのプリンターでも印刷できます。ラベルは荷物に平らに貼り、端で折れないようにしてください。",
  "training.lessons.print-shipping-label.step5": "郵便料金を配送業者から購入した場合は、代わりにそのラベルファイルを注文に保存してください：「配送業者のラベル」セクションで、配送業者から受け取ったPDF、PNG、JPGをアップロードします。あなたの記録として注文に残り、実際の4×6サイズで印刷されます — そして、使いたいときにはアプリ自身の宛名ラベルもいつでもそこにあります。",
  "training.lessons.print-shipping-label.title": "配送ラベルを印刷する",
  "pos.provider.clover": "Clover",
