  "settings.install.title": "アプリをダウンロード",
  "settings.install.description": "Luminous StockHaven をこのデバイスに入れましょう — なくなった場合は取り戻せます。このウェブサイトから直接インストールされ（アプリストアは不要）、ホーム画面からフルスクリーンで開きます。",
  "settings.install.button": "アプリをダウンロード",
  "settings.install.installed": "アプリはすでにこのデバイスにあります — 今、インストールされたアプリを使用しています。",
  "settings.install.manualIntro": "現在、インストールの案内は利用できません。それでも手動でアプリを追加できます：",
  "settings.install.iosSteps": "Safari で、共有ボタンをタップし、「ホーム画面に追加」をタップし、「追加」をタップします。アプリは他のアプリと同じようにホーム画面に置かれます。",
  "settings.install.androidSteps": "ブラウザで、メニュー（3つの点）をタップし、「アプリをインストール」または「ホーム画面に追加」をタップして確認します。アプリは他のアプリと同じようにホーム画面に置かれます。",
  "settings.install.desktopSteps": "ブラウザのアドレスバーで、インストールアイコンが表示されていればクリックします。アイコンがない場合は、ブラウザメニューを開き、「Luminous StockHaven をインストール」または「デスクトップに追加」を選択します。",
  "staffWelcome.title": "Luminous StockHaven へようこそ",
  "staffWelcome.defaultGreeting": "こんにちは、{name}",
  "staffWelcome.defaultStoreLine": "あなたは今 {store} の一員です — このお店はあなたのものでもあります。",
  "staffWelcome.defaultTrainingLine": "あなたのトレーニングは準備できています — すべてを一歩ずつ案内します。",
  "staffWelcome.defaultGladLine": "あなたがここにいてくれてうれしいです。",
  "staffWelcome.start": "トレーニングを始める",
  "staffWelcome.skip": "今はスキップ",
  "staffWelcome.editor.title": "新しいスタッフへの歓迎メッセージ",
  "staffWelcome.editor.description": "新しい人が最初のサインインで、何よりも先に一度だけ読む言葉です。あなた自身の言葉で書いて、あなたのお店らしく感じられるようにしてください。",
  "staffWelcome.editor.permanentNote": "この最初の行はアプリそのものです — 常に表示され、変更したり削除したりすることはできません。",
  "staffWelcome.editor.tokens": "{name} はその人の名前が表示される場所に、{store} はあなたのお店の名前が表示される場所に書いてください — アプリが一人ひとりに合わせて埋めます。",
  "staffWelcome.editor.emptyNote": "アプリの標準の歓迎（ボックス内に薄く表示）を使う場合は、ボックスを空のままにしてください。新しい人が空白のページを見ることは決してありません。",
  "staffWelcome.editor.save": "歓迎メッセージを保存",
  "staffWelcome.editor.saved": "歓迎メッセージを保存しました。",
  "training.lessons.staff-shift-windows.title": "あなたのサインインはシフトに従います",
  "training.lessons.staff-shift-windows.step1": "予定されたシフトが始まる約10分前からサインインできます。それまではアプリは閉じたままです — サインインページが次のシフトの開始時刻を教えてくれます。",
  "training.lessons.staff-shift-windows.step2": "退勤すると、自分のページを確認するために10分あります。次の予定日までログアウトされるからです。",
  "training.lessons.staff-shift-windows.step3": "その10分以内に再び出勤すると、ログアウトはキャンセルされ、サインインしたままになります。",
  "training.lessons.staff-shift-windows.step4": "スケジュールにシフトがないということは、その日はサインインできないということです。自分がスケジュールに入っているはずだと思う場合は、マネージャーまたはオーナーに聞いてください — あなたのドアを開けるスケジュールを公開するのは彼らです。",
  "training.lessons.manager-shift-windows.title": "スケジュールを公開するとアクセスが開閉します",
  "training.lessons.manager-shift-windows.step1": "チームのために公開するスケジュールは、シフトのリスト以上のものです：それは一人ひとりのアプリアクセスを開閉するものです。チームメンバーは、あなたが彼のために公開したシフトの約10分前からサインインできます — それより前はできません。",
  "training.lessons.manager-shift-windows.step2": "彼が退勤すると、時間を確認するために約10分あり、その後アプリは次の予定シフトまで彼をログアウトします。その日に公開されたシフトがないということは、その日はサインインできないということです。",
  "training.lessons.manager-shift-windows.step3": "シフトは慎重に公開してください：シフトが欠けていたり間違っていたりすると、その人はスケジュールからだけでなく、アプリからも締め出されます。誰かが入れないと言ったら、まず彼のスケジュールを確認してください。",
  "training.lessons.manager-shift-windows.step4": "あなた自身のアクセスも同じ仕組みで、一つ上のレベルで働きます：オーナーがあなたのために公開するスケジュールが、あなたのシフトの約10分前にあなたのウィンドウを開き、退勤の約10分後にあなたのセッションは閉じられます。",
  "training.lessons.owner-shift-windows.title": "シフトウィンドウ：スケジュールがアクセスを開閉します",
  "training.lessons.owner-shift-windows.step1": "アクセスはあなたが公開するスケジュールに従います。スタッフまたはマネージャーは、予定されたシフトの約10分前からサインインできます — それより前はできません。シフト外ではアプリは彼らに対して閉じたままになり、お店の情報は勤務中の人のもとに残ります。",
  "training.lessons.owner-shift-windows.step2": "彼らが退勤すると、時間を確認するために約10分あり、その後アプリは次の予定シフトまで自動的に彼らをログアウトします。その10分以内に再び出勤すると、ログアウトはキャンセルされます。",
  "training.lessons.owner-shift-windows.step3": "その日に公開されたシフトがないということは、その日にウィンドウがないということです：スケジュールに入っていない人はサインインできません。ワークフォースでスケジュールを公開すれば、彼のドアも一緒に開きます。",
  "training.lessons.owner-shift-windows.step4": "あなただけが唯一の例外です：オーナーをスケジュールする人はいないので、あなたのサインインにウィンドウは決してありません。マネージャーはあなたが彼のために公開するスケジュールによって制限され、スタッフが彼らのために公開されたスケジュールによって制限されるのと同じです。",
  "settings.install.ownerNote": "アプリストアがいつかアプリの使用を妨げた場合、このリンクでこのウェブサイトから直接アプリを入手できます — ストアは不要です。",
  "layout.signOutLink": "ログアウト",
