  "training.lessons.messages-private.step5": "ボイスノートも送信できます。メッセージボックスの横のマイクをタップして話し、停止をタップします。まず聞いてから — 送信するか、削除してもう一度録音してください。誰かから送られてきたら、再生をタップして本人の声を聞けます。",
  "training.lessons.owner-messages-oversight.step5": "既読マーク：チームメンバーがあなたが送ったメッセージを読むと、既読としてマークされたのが見えます。スタッフとマネージャーは互いの既読マークを同じように、双方向で見られます。",
  "training.lessons.owner-messages-oversight.step6": "あなた自身の既読は見えません。スタッフメンバーがあなたに送ったメッセージをあなたが読んでも、相手に既読マークは決して表示されません — そして、チームの会話がアプリに保存され、オーナーであるあなたが読めることを、チームに伝える必要はありません。その見守りは、あなたのお店を守ることの一部です。",
  "training.lessons.owner-messages-oversight.step7": "スタッフ同士の否定的なメッセージについてどうするかは、あなた次第です。見過ごすか、誰かに静かに話すか、対処するか — 選択はあなたのもので、どこで見たかを言う必要は決してありません。",
