  "settings.policies.title": "あなたの店舗ポリシーと利用規約",
  "settings.policies.ownerDescription": "あなたのお店、あなたのルール。店舗ポリシーと利用規約をここに書きましょう — 入力するか、ファイルをアップロードしてください。新しいチームメンバーは開始時に一度だけこれらを見て、チーム全員がいつでもここで読むことができます。変更できるのはあなただけです。",
