  "staffWelcome.policiesIntro": "始める前に: オーナーが書いた、あなたのお店のポリシーと規約です。",
  "plansLib.includes.storePolicies": "設定の中にある、あなた自身の店舗ポリシーと規約。チーム全員が読めます",
  "apiErrors.businessPoliciesOwnerOnly": "このお店のポリシーと規約を変更できるのはオーナーだけです。",
  "apiErrors.policyFileInvalid": "25 MB未満のPDF、テキスト、Word、またはOpenDocumentファイルを送信してください。",
  "apiErrors.policyTextTooLong": "そのドキュメントはここに入力するには長すぎます。代わりにファイルとしてアップロードできます。",
  "training.lessons.owner-store-policies.title": "あなたの店舗ポリシーと利用規約",
  "training.lessons.owner-store-policies.step1": "設定を開き、「店舗ポリシーと利用規約」カードを探してください。そこには2つのドキュメントがあります: 店舗ポリシー — あなたのお店のハウスルール — と、利用規約です。",
  "training.lessons.owner-store-policies.step2": "各ドキュメントはその場で入力するか、ファイルとしてアップロードできます(PDF、テキスト、Word、またはOpenDocument、25 MBまで)。どちらか一方です: テキストを保存するとファイルが置き換わり、ファイルをアップロードするとテキストが置き換わります。ドキュメントを削除すると空になります。",
  "training.lessons.owner-store-policies.step3": "チームは両方のドキュメントを一度だけ、初めて開始するときのウェルカムページで見て、その後は設定の中でいつでも読めます。チームにとっては読み取り専用です — 書いたり変更したりできるのはあなただけです。",
  "training.lessons.owner-store-policies.step4": "各ビジネスは自分のドキュメントを保持します: ここに書いたものはこのお店だけのもので、別のビジネスに表示されることは決してありません。Luminous StockHaven自体の規約とポリシーは、あなたのものの隣に設定の中にあり、全員がそれらも読めます。",
  "training.lessons.welcome-basics.step5": "あなたのお店のポリシーと規約は、ウェルカムページで一度表示され、設定の中に置かれて、いつでも読めます。",
