  "staff.memberDialog.lowStockAccessHint": "最初のチェックを入れると、このメンバーには在庫低下のアラート — 「注意が必要です」のボックス、在庫低下のページ、低レベルのマーク — が表示されます。2つ目のチェックを入れると、商品の再注文ポイントを変更できます。チェックがない場合、再注文ポイントの欄は表示されたままですが、変更は保存されません。",
  "apiErrors.reorderChangeReserved": "再注文ポイントを変更できるのは、オーナー、または再注文ポイントの変更をオーナーに許可されたチームメンバーだけです。",
