  "settings.policyQuiz.title": "チームへの質問",
  "staff.memberDialog.trainingAccessHint": "店舗ポリシーと規約を読むことは全員のためです。これらのチェックは、オーナーが設定で各文書の横に作るクイズトレーニングを割り当てます。",
  "staffLib.area.trainingAccess": "ポリシークイズトレーニング",
  "staffLib.perm.trainingPoliciesQuiz": "店舗ポリシーのクイズトレーニング",
  "staffLib.perm.trainingTermsQuiz": "利用規約のクイズトレーニング",
  "training.comment.placeholder": "このレッスンについて何でも…",
  "training.comment.send": "コメントを送信",
  "training.comment.sent": "あなたのコメントはオーナーに届けられました。",
  "training.comment.title": "オーナーにコメントを残す",
  "training.lessons.download-app.step1": "Luminous StockHaven は本物のアプリのようにあなたの携帯電話やコンピュータに住むことができます — アプリストアは必要ありません。",
  "training.lessons.download-app.step2": "設定を開いて、アプリをダウンロードカードを見つけてください。すべての役割、両方のプランでそこにあります。",
  "training.lessons.download-app.step3": "インストールボタンをタップし、デバイスの指示に従ってください。アプリは店舗の名前とアイコンとともにホーム画面に届きます。",
  "training.lessons.download-app.step4": "それからはホーム画面から開いてください — 同じ方法でサインインし、同じ店舗を表示します。",
  "training.lessons.download-app.title": "アプリをデバイスにダウンロード",
  "training.lessons.mgr-tax-rate.step1": "注文には売上税率がかかる場合があります。オーナーが設定で税率自体を設定します。店舗全体で一つの税率です。",
  "training.lessons.mgr-tax-rate.step2": "オーナーがあなたのスタッフ記録で税金セクションにチェックを入れると、税率があなたの設定にも表示され、そこで最新の状態に保つことができます。",
  "training.lessons.mgr-tax-rate.step3": "税率はパーセントです — 8.25 は、お客様が注文の商品に加えて 8.25% の税金を支払うことを意味します。",
  "training.lessons.mgr-tax-rate.step4": "税率が変わると、新しい注文は新しい税率を使います。すでに注文されたものは、作られたときの税率を保持します。",
  "training.lessons.mgr-tax-rate.step5": "オーナーが税金を自動に切り替えると、新しい注文は、州が注文に記載された時点で、お客様の州の基本税率で税金を入力し、州が変更されると再入力します。これらは州の基本税率です。地方税がさらに加わる場合があります。州のない注文、または米国外からの注文は、お店の固定税率を使います — そして、注文に入力された税金が常に優先されます。",
  "training.lessons.mgr-tax-rate.title": "店舗の税率",
  "training.lessons.owner-confidentiality.step5": "これが全体の地図です。あなたのチームは自分の仕事を見ます — 自分のスケジュール、自分のタスク、自分の給与明細、自分のメッセージ、そして自分の役割が開く店舗画面。彼らはあなたのトライアル、ビジネスがどのプランにいるか、プランの費用、支払いが通ったかどうか、プランの上限に達したことを決して見ません。お金の表面 — 請求、請求書、支払い方法 — は常にオーナーのみです。",
  "training.lessons.owner-confidentiality.step6": "アカウントが停止された場合、あなたのチームが見る正確なメッセージはこれです: “変更は現在オフになっています。現時点では何も追加または変更できません — 何か必要な場合はビジネスのオーナーに聞いてください。” その中にはプラン、価格、支払いの名前は一切ありません。",
  "training.lessons.owner-confidentiality.step7": "そしてプランの上限が何かを止める場合、正確なメッセージはこれです: “これは今追加できません — 事業主にお尋ねください。” 上限に達したとは決して言いません — それはあなたとアプリの間だけのことです。",
  "training.lessons.staff-builds.step1": "ビルドは製品をまとめて売れる一つのものにします — バンドル、キット、ギフトセット。ビルドはメニューのビルド画面にあります。",
  "training.lessons.staff-builds.step2": "ビルドを開いて、何が入っているか見てください: 各部品製品と、ビルドがそれぞれをいくつ使うか。",
  "training.lessons.staff-builds.step3": "ビルドが作られたり売れたりすると、その部品の在庫も一緒に動きます — アプリがあなたのために数を正直に保ちます。",
  "training.lessons.staff-builds.step4": "部品が不足していたり数が間違っているように見えたら、推測せずにマネージャーに伝えてください — ビルドは一度に多くの製品に触れます。",
  "training.lessons.staff-builds.title": "ビルドとバンドル",
  "training.lessons.staff-cross-store.step1": "あなたのビジネスに複数の店舗やサイトがある場合、店舗同士で在庫を頼み合うことができます。そのリクエストは店舗間受信箱に届きます。",
  "training.lessons.staff-cross-store.step2": "メニューから受信箱を開いて、他の店舗が何を頼んでいるか、あなたの店舗に何が送られたかを見てください。",
  "training.lessons.staff-cross-store.step3": "リクエストには、マネージャーが示した方法でのみ答えてください — 在庫を送り出すと、自分の店舗の数が変わります。",
  "training.lessons.staff-cross-store.step4": "リクエストが間違っているように見えたら — 間違った商品、または持っているより多い — 推測しないでください。マネージャーに知らせてください。",
  "training.lessons.staff-cross-store.title": "店舗間受信箱",
  "training.lessons.staff-reports.step1": "レポートは店舗の数字 — 売上、在庫など — を一つの場所に集めます。レポートはメニューにあります。",
  "training.lessons.staff-reports.step2": "レポートを開いて、対象期間の数字を見てください。日付はレポートの一部です: 同じレポートでも週が違えば違う物語を語ります。",
  "training.lessons.staff-reports.step3": "一部のレポートはアプリからファイルとして保存できます。マネージャーやオーナーに頼まれたときだけ、レポートを外に保存してください。",
  "training.lessons.staff-reports.step4": "レポートの数字は店舗の実際の仕事から来ます — 注文、数、動き — だから他の場所での正直な入力がレポートを真実に保ちます。",
  "training.lessons.staff-reports.title": "レポートを読む",
  "training.lessons.welcome-basics.step6": "終わったら、サインアウトしてください: サインアウトリンクはすべてのページの一番下、著作権行のすぐ上にあります。サインアウトすると、すべての場所、すべてのデバイスでサインアウトします — 共有画面で誰もあなたのアカウントに入り込むことはできません。",
  "training.policy.belowLine": "それはラインの下です — もう一度やってみてください。",
