  "training.lessons.your-profile-photo.title": "プロフィール写真",
  "training.lessons.your-profile-photo.step1": "オーナーが承認すると、あなたの写真がアプリ上部の名前の横、「スタッフ」ページ、メッセージの横に表示されます。それまではイニシャルだけが表示されます。",
  "training.lessons.your-profile-photo.step2": "「設定」を開き、「プロフィール写真」を見つけます。自分の写真を選んで送信してください。写真はオーナーに送られ承認を待ちます。待っている間はどこにも表示されません。",
  "training.lessons.your-profile-photo.step3": "オーナーが承認すると、ベルが鳴り、写真が表示され始めます。承認されなかった場合は、別の写真を選んで送信してください。",
  "training.lessons.your-profile-photo.step4": "写真の変更も同じです。新しい写真は承認を待ち、新しい写真が承認されるまで現在の写真がそのまま残ります。変更が承認されなかった場合は、もう一方の写真が残ります。",
  "training.lessons.owner-profile-photos.title": "プロフィール写真とあなたの名前",
  "training.lessons.owner-profile-photos.step1": "全員の写真は、アプリ上部、あなたの「スタッフ」ページ、メッセージの横など、名前の横に表示されます。チームメンバーの写真は、あなたが承認するまでどこにも表示されません。承認はあなただけの権限であり、自分の写真を自分で承認することはできません。",
  "training.lessons.owner-profile-photos.step2": "誰かが写真を送信すると、ベルが鳴ります。「スタッフ」ページを開いて写真を確認し、「承認」または「承認しない」を選んでください。承認しない場合、その人には別の写真を選ぶよう伝えられます。",
  "training.lessons.owner-profile-photos.step3": "誰かが写真を変更した場合、新しい写真も同じようにあなたの承認を待ちます。待っている間、現在の写真はそのまま残り、変更を承認しない場合も残ります。",
  "training.lessons.owner-profile-photos.step4": "あなた自身の写真は承認不要です。「設定」の「プロフィール写真」で設定してください。同じカードにはあなたの名前もあります。そこで設定した名前は、アプリ内や「メッセージ」を含め、チームが見るあらゆる場所で「オーナー」という言葉に置き換わります。",
