  "staffLib.perm.staffClockBoard": "勤怠ボードと打刻漏れの退勤",
  "staffLib.perm.staffCallins": "呼び出し",
  "staffLib.area.clockAccess": "勤怠ボードと呼び出し",
  "staff.memberDialog.clockAccessHint": "マネージャーのみ — 2つの別々のチェックです。勤怠ボードと打刻漏れの退勤があると、このマネージャーはチームの勤怠記録を見て、スタッフページから勤務時間の記録を修正できます。呼び出しがあると、このマネージャーは呼び出しウィンドウを開き、シフトが入っていない人に働いてもらえます。これらのチェックはスタッフには何もしません。",
