  "apiErrors.clockFix.invalidTime": "各時刻を有効な日付と時刻として送信してください。",
  "apiErrors.notFound.timeEntryFound": "勤務時間の記録が見つかりません。",
  "training.lessons.mgr-clock-callin.title": "呼び出しと打刻の修正",
  "training.lessons.mgr-clock-callin.step1": "オーナーはマネージャーに2つの別々のチェックを与えられます。呼び出しではスタッフメンバーの呼び出しウィンドウを開くことができ、勤怠ボードと打刻漏れの退勤ではチームの勤怠ボードを見て、スタッフページから勤務時間の記録を修正できます。各チェックは単独で機能します — マネージャーは片方だけを持つこともできます。",
  "training.lessons.mgr-clock-callin.step2": "呼び出しウィンドウがあると、カバーするシフトがないときでもサインインして出勤打刻できます。スタッフページの「呼び出しと退勤打刻の忘れ」カードから開きます。",
  "training.lessons.mgr-clock-callin.step3": "ウィンドウは、その人が退勤打刻するまで — その後に通常の10分間のサインアウト猶予が続きます — またはあなたかオーナーが早めに閉じるまで開いたままです。自動で閉じることはありません。",
  "training.lessons.mgr-clock-callin.step4": "誰かが退勤打刻を忘れると、予定されたシフトが終わった時点で、その記録はスタッフページと給与計算にフラグが立ち、あなたとオーナーに通知されます。記録は修正されるまでカウントし続けます。",
  "training.lessons.mgr-clock-callin.step5": "スタッフページから記録を修正します：出勤、退勤、休憩の時刻を設定してください。マネージャーが修正できるのはスタッフの記録だけです — マネージャー自身の記録はオーナーが修正します。",
  "staffLib.perm.staffDocuments": "スタッフ文書",
  "staffLib.area.documentsAccess": "スタッフ文書",
  "staff.memberDialog.documentsAccessHint": "マネージャー専用 — このチェックを付けると、このマネージャーはスタッフメンバーの文書ファイルを開けるようになります。各人のために保管する書類、たとえば W-4 フォーム、求職申込書、身分証明書のコピーなどです。最初に確認を求められます — これらのファイルには社会保障番号と生年月日が含まれています。このチェックはスタッフには何もしません。",
  "staff.documentsWarning.body": "この人は、社会保障番号と生年月日を含む、あなたのスタッフメンバーに関する機密情報を見ることができるようになります。",
