  "staff.documents.mineDesc": "オーナーがあなたのために保管している書類 — W-4 フォーム、求職申込書、税務フォーム、身分証明書のコピー。これはあなた自身のファイルです。中身はすべて開いたり、ダウンロードしたり、印刷したりできますが、ここでは何も変更できません。",
