  "nav.xstoreMessages": "店舗間メッセージ",
  "plansLib.businessIncludes.xstoreMessages": "店舗間メッセージ — すべての事業所のチーム全員とつながれます",
  "xstore.title": "店舗間メッセージ",
  "xstore.help": "このアカウントの全員が、すべての事業所を越えて、一つの受信箱に集まります。ここから誰にでもメッセージを送れます。テキストでも音声でも送れ、配信済みと既読の表示も付きます。店舗内のメッセージはこれまで通りです。",
  "xstore.empty": "まだ会話がありません。「新しいメッセージ」から始めましょう。",
  "xstore.noPeople": "まだメッセージを送れる相手がいません。事業所に参加してサインインすると、ここに表示されます。",
  "xstore.deliveredLabel": "配信済み",
  "apiErrors.planGated.crossStoreMessagesPartBusiness": "店舗間メッセージはビジネスプランに含まれています。",
  "apiErrors.invalidValue.personNotPartAccount": "その方はこのアカウントのメンバーではありません。",
  "training.lessons.owner-xstore-messages.title": "店舗を越えたメッセージ（オーナー向け）",
  "training.lessons.owner-xstore-messages.step1": "店舗間メッセージは、メッセージとは別の、もう一つの受信箱です。メッセージは今いる店舗のためのものですが、こちらはあなたのアカウントの全員、あなたが所有するすべての事業所（最大5件まで）に届きます。",
  "training.lessons.owner-xstore-messages.step2": "メニューから店舗間メッセージを開き、一覧の誰とでも会話を始められます。一覧には、すべての事業所のチームメンバーのうちサインインした全員が、勤務先の店舗と一緒に表示されます。",
  "training.lessons.owner-xstore-messages.step3": "写真も一緒に表示されます。各メンバーには承認済みのプロフィール写真が表示され、写真がない場合はイニシャルが表示されます。すべてのメッセージには送信した日付と時刻が付きます。",
  "training.lessons.owner-xstore-messages.step4": "自分のメッセージの下には、届くと「配信済み」、相手が会話を開くと「既読」と表示されます。音声メモも、メッセージと同じようにここで使えます。",
  "training.lessons.owner-xstore-messages.step5": "こちらの会話は、その二人の間だけのプライベートなものです。店舗内のメッセージに対するあなたの確認権限は、店舗を越えては及びません。",
  "training.lessons.mgr-xstore-messages.title": "店舗を越えたメッセージ（マネージャー向け）",
  "training.lessons.mgr-xstore-messages.step1": "店舗間メッセージは、今いる店舗だけでなく、このアカウントの全員に、すべての事業所を越えて届きます。メニューの中にあり、メッセージとは分かれています。",
  "training.lessons.mgr-xstore-messages.step2": "一覧から会話を始めましょう。サインインしたチームメンバー全員が、名前の横に勤務先の店舗と一緒に表示されています。",
  "training.lessons.mgr-xstore-messages.step3": "テキストを送るか、音声メモを録音できます。音声メモは送信前に聞き直したり、破棄したり、送信したりできます。メッセージと同じです。",
  "training.lessons.mgr-xstore-messages.step4": "あなたのメッセージは、届くと「配信済み」、相手が会話を開くと「既読」と表示されます。名前の横の写真は、その方の承認済みのプロフィール写真です。",
  "training.lessons.staff-xstore-messages.title": "店舗を越えたメッセージ",
  "training.lessons.staff-xstore-messages.step1": "店舗間メッセージでは、このアカウントの全員に、オーナーのどの事業所にいる方にも連絡できます。ほかの店舗への質問を、もう待つ必要はありません。",
  "training.lessons.staff-xstore-messages.step2": "メニューから開いて、相手を選んで書きましょう。必要な方が一覧にいない場合は、まだサインインしていません。サインインするとすぐに表示されます。",
  "training.lessons.staff-xstore-messages.step3": "ここでも音声メモを送れます。録音して、聞き直してから、送信するか破棄してください。すべてのメッセージには送信した日付と時刻が表示されます。",
  "training.lessons.staff-xstore-messages.step4": "メッセージを送ると、届いた時点で「配信済み」、相手が会話を開くと「既読」と表示されます。会話はあなたと相手の二人だけのプライベートなものです。",
