  "training.lessons.owner-restaurant-ops.title": "レストラン運営（オーナー向け）",
  "training.lessons.owner-restaurant-ops.step1": "仕入先請求書はレストランコーナーにあります。仕入先の請求を入力し、発注書にリンクすると、アプリが発注数・受入数・請求数を並べて3点照合し、不足・過剰・単価違いの行に印をつけます。",
  "training.lessons.owner-restaurant-ops.step2": "請求書の行が、記録上のコストと異なる価格で商品を請求している場合、請求書ページに価格アラートが開きます。アラートを受け入れると商品のコストが請求価格に更新され、却下するとコストはそのままです。",
  "training.lessons.owner-restaurant-ops.step3": "廃棄記録には、キッチンが捨てるものすべてと理由 — 傷み、作りすぎ、仕込みミス、返品、こぼれ、その他 — が残り、記録すると在庫が自動で棚から減ります。期限バッチは期限の早い順に並ぶので、いちばん早い使用期限のものから使え、チェックしたバッチの日付ラベルを印刷できます。",
  "training.lessons.owner-restaurant-ops.step4": "アレルゲン表は、9大アレルゲンに対して各料理のレシピ材料からアレルゲンを割り出すので、お客様の質問に記憶ではなく記録から答えられます。温度記録、品切れボード、スタッフミールはチーム全員に開かれています — チェックは不要です。日々の記録は、誰でもできるからこそ機能するのです。",
  "training.lessons.owner-restaurant-ops.step5": "メニュー分析は、各料理をどれだけ売れ、どれだけ稼いだかで配置します：スター、馬車馬、パズル、犬です。差異ページは、レシピ上棚から出るはずだったものと、スタッフミール、廃棄、その他出たものを比べます — 残ったものが未説明です。会計エクスポートは、受け入れた仕入れ、廃棄、スタッフミールとレシピ消費を、帳簿のための1つの台帳に集めます。",
  "training.lessons.staff-restaurant-daily.title": "キッチンの毎日の習慣",
  "training.lessons.staff-restaurant-daily.step1": "何かを捨てたら、その日のうちに廃棄記録に残してください：何を、どれだけ、なぜか — 傷み、作りすぎ、仕込みミス、返品、こぼれ、その他。記録すると在庫が自動で棚から減ります。在庫を別に調整しないでください。",
  "training.lessons.staff-restaurant-daily.step2": "冷蔵庫・冷凍庫・保温の温度は、チェックするたびに記録してください。記録にはあなたの名前と時刻が残り、安全範囲外の測定値には印がつきます — 対処したことを是正措置として書いてください。",
  "training.lessons.staff-restaurant-daily.step3": "品切れボードは、今品切れのものです。なくなった瞬間に品目を掲示してチーム全員が一度に知れるようにし、戻ったら外してください — ボードには誰がいつ外したかが残ります。",
  "training.lessons.staff-restaurant-daily.step4": "チームが食事をしたら、スタッフミールとして記録してください。各食事は、その料理を棚から減らし、料理のレシピ材料を販売と同じように使います。スタッフミールはその日の実際のコストで、記録に属するものです。",
  "training.lessons.mgr-restaurant-invoices.title": "請求書、バッチとバッチ実行",
  "training.lessons.mgr-restaurant-invoices.step1": "オーナーはあなたに「レシピを作成」チェックを託しました。それはキッチンの作成作業も開きます：仕入先請求書、期限バッチ、バッチ生産です。明細行 — 商品、数量、請求単価 — とともに仕入先請求書を入力し、発注書がある場合はリンクしてください。",
  "training.lessons.mgr-restaurant-invoices.step2": "発注書がリンクされると、請求書は行ごとに3点照合されます：発注されたもの、受け入れたもの、請求されたもの。行は、一致、不足、過剰、単価違い、または発注に全くない、のいずれかで返ってきます。",
  "training.lessons.mgr-restaurant-invoices.step3": "請求価格が商品の記録上のコストと異なる場合、価格アラートが開きます。アラートを受け入れると商品のコストが新しい請求価格になり、却下すると何も変わりません。同じ請求書と商品について、開いているアラートは一度に1つだけです。",
  "training.lessons.mgr-restaurant-invoices.step4": "在庫は使用期限つきの期限バッチとして受け入れてください。期限ページがバッチを期限の早い順に保ちます。バッチ実行はレシピを設定回数分作ります：レシピの材料を使い切り、完成した仕込み商品を棚に載せます — レシピはまずその仕込み商品にリンクされていなければなりません。",
  "training.lessons.mgr-restaurant-invoices.step5": "仕入先が請求書に対して返金したら——破損したケース、不足した納品、訂正された価格——請求書ページで、その請求書に対してクレジットメモとして記録してください。仕入先は請求書自体から取得され、メモは請求書の未払い分に対して計算されます：請求書には適用済みクレジットと未払い残高が表示されます。クレジットがその請求書を超えることは決してなく、メモを無効化すると記録には残りながら計算が止まります。 メモが紙で必要なときは、その行から印刷してください。印刷されたシートは仕入先のクレジットに関するあなた自身の記録であり、仕入先の文書ではありません。",
  "training.lessons.mgr-restaurant-reports.title": "メニュー分析、差異と帳簿",
  "training.lessons.mgr-restaurant-reports.step1": "オーナーはあなたに「料理のお金」チェックを託しました。それはキッチンのお金のレポートも開きます：メニュー分析、差異、会計エクスポートです。これらの数字は、料理のお金すべてと同様、ビジネスの中にとどまります。",
  "training.lessons.mgr-restaurant-reports.step2": "メニュー分析は、期間内に各料理がどれだけ売れ、どれだけ稼いだかで配置します。スターはよく売れてよく稼ぎ、馬車馬はよく売れるがあまり稼がず、パズルはよく稼ぐがあまり売れず、犬はどちらでもありません。",
  "training.lessons.mgr-restaurant-reports.step3": "差異ページは商品ごとに動きます：レシピ上棚から出るはずだったものの横に、スタッフミール、廃棄、その他すべての出庫。残ったものは未説明です — そして未説明こそ、説明しに行くべき数字です。",
  "training.lessons.mgr-restaurant-reports.step4": "会計エクスポートはキッチンのための1つの台帳です：受け入れた仕入れ、廃棄、スタッフミールとレシピ消費。各行に日付、数量、コストがつき、帳簿を付ける人に渡せる形です。",
  "apiErrors.invalidReference.recipeMustBelongBusiness": "レシピはこのビジネスに属していなければなりません。",
