  "storefronts.ebayDesc": "eBay ストアフロントを一度接続してください。eBay で商品が売れると、その数がここで自動的に減り、販売が移動履歴に記録されます — スキャンして出庫したのと同じです。販売は一方向にだけ流れます：eBay からアプリへです。",
