  "training.own.pendingNote": "あなたの回答はオーナーの手元にあります。オーナーが合格とマークすると、このトレーニングは完了となります。",
  "plansLib.includes.ownTraining": "独自のトレーニングを追加 — チームのために独自のトレーニングとクイズを書けます",
  "training.lessons.owner-own-training.title": "独自のトレーニングの追加",
  "training.lessons.owner-own-training.step1": "トレーニングページの一番最後に「独自のトレーニングを追加」のボックスがあります。開いて、新しいトレーニングを始め、タイトルを付けてください — 安全ルール、注意事項、あなたのやり方。",
  "training.lessons.owner-own-training.step2": "トレーニング本文をボックスに自分の言葉で書くか、代わりにファイルとしてアップロードしてください — PDF、テキスト、Word、OpenDocumentファイル。入力した言葉は保存済みファイルに置き換わり、ファイルは入力した言葉に置き換わります。",
  "training.lessons.owner-own-training.step3": "その下にクイズを作ってください。好きなだけの問題を、選択式と記述式を自由に混ぜて。記述式の問題には、期待する回答を書いてください。選択式では、正しいものにマークしてください。",
  "training.lessons.owner-own-training.step4": "合格ラインを設定し、記述式の回答の判定方法を選んでください。解答キーとほぼ一言一句照合するか、あなたに送って合格とマークするか差し戻すか。次に、このトレーニングを受けるチームメンバーに正確にチェックを入れてください — その人たちだけがこれを見ます。",
  "training.lessons.owner-own-training.step5": "保存したトレーニングはそれぞれボックスの中で独立し、独自の問題、ライン、チェックを持ち、いくつでも追加できます。結果は各トレーニングの下のボックスに届きます。トレーニングは、サーバーが合格した実施分を確認したときにのみ完了となります — 採点モードでは、あなたが合格とマークしたときです。",
  "apiErrors.ownTrainingOwnerWrites": "これらのトレーニングを書くのはオーナーだけです。",
  "apiErrors.ownTrainingNotHere": "そのトレーニングはここにありません。",
