  "print.pool.title": "バーコードを生成",
  "print.pool.intro": "商品が存在する前にバーコードを作成します。印刷して、独自のバーコードを持たない商品に貼ると、後でスキャンされたときにアプリがそのコードを認識し、商品の追加を提案します。",
  "print.pool.countLabel": "バーコードはいくつ必要ですか？",
  "print.pool.generate": "生成",
  "print.pool.generating": "生成中…",
  "print.pool.minted": "{count} 件の新しいバーコードがプールに追加されました。",
  "print.pool.waiting": "未使用のバーコード {count} 件がプールで待機しています。",
  "print.pool.printNow": "今すぐ印刷",
  "print.pool.savePdf": "PDFとして保存",
  "print.pool.failed": "それらのバーコードを作成できませんでした。もう一度お試しください。",
  "scan.pool.title": "あなたが印刷したバーコードの一つ",
  "scan.pool.body": "これはまだあなたの店舗の商品ではありません — 事前に印刷したバーコードです。商品として追加しますか？",
  "plansLib.includes.barcodePool": "バーコードプール — バーコードを事前に印刷し、各商品はそのバーコードがスキャンされたときに加えます",
  "training.lessons.owner-barcode-pool.title": "商品より先にバーコードを印刷する",
  "training.lessons.owner-barcode-pool.step1": "商品の中には独自のバーコードを持たないものがあります — 手作りの品、あなた自身のブックバッグ、自分で作ったり組み合わせたりするものすべてです。印刷セクションの「バーコードを生成」の入口は、商品が存在する前にコードを作成します。",
  "training.lessons.owner-barcode-pool.step2": "必要な数を伝えてください — 上限はありません — アプリはあなたのビジネスのバーコードプールにその数だけ新しいコードを発行します。それらはあなたのビジネスだけのもので、二度と配られることはなく、作成しても商品も在庫も生まれません。",
  "training.lessons.owner-barcode-pool.step3": "作成された瞬間に選んでください：今すぐラベルとして印刷するか、後で印刷するためにPDFとして保存するか。どちらでもコードはプールに入り、印刷されたラベルはプールと正確に一致します。",
  "training.lessons.owner-barcode-pool.step4": "品物を作るたびにラベルを貼ってください。未使用のコードはプールでただ待つだけです — 急ぐ必要はなく、期限も切れません。",
  "training.lessons.owner-barcode-pool.step5": "ラベルの貼られた品物が後でスキャンされると、アプリは自ら印刷したコードを認識し、コードが既に入力された状態で商品の追加を提案します。追加されれば、そのコードはその商品のコードとなり、他のコードと同じようにスキャンされます。",
  "apiErrors.poolOwnerMints": "プール用のバーコードを作成するのはオーナーだけです。",
  "apiErrors.poolCount": "バーコードがいくつ必要か伝えてください — 1以上の整数です。",
