  "apiErrors.checklistsManage": "オーナー、またはオーナーがチェックリストテンプレートのチェックを与えた人だけが、チェックリストのテンプレートを変更できます。",
  "apiErrors.checklistProof": "この項目は、チェックする前にその証拠が必要です。",
  "apiErrors.checklistName": "チェックリストに名前を付けてください。",
  "apiErrors.checklistItems": "チェックリストに少なくとも1つの項目を追加してください。",
  "apiErrors.checklistUntick": "この項目にチェックした本人、マネージャー、またはオーナーだけが、そのチェックを外せます。",
  "training.lessons.staff-checklists.title": "チェックリストで作業する",
  "training.lessons.staff-checklists.step1": "チェックリストはあなたのビジネスが回っているリストです — 開店、閉店、清掃、そしてオーナーが設定するすべて。チェックリストの中にあります:今日のリストが一番上にあり、チェックできる状態です。",
  "training.lessons.staff-checklists.step2": "項目は、本当にやったときにチェックしてください。どのチェックも、誰がいつやったかを記録するので、次の人 — そして家にいるオーナー — が、何が終わり何がまだ残っているかを見られます。",
  "training.lessons.staff-checklists.step3": "一部の項目は、チェックする前に証拠を求めます:終わった仕事の写真、コードのスキャン、または入力した温度。まず証拠を追加してからチェックしてください — それなしでは項目はチェックされません。",
  "training.lessons.staff-checklists.step4": "何か間違えてチェックしましたか?チェックを外してください — ただし自分のものだけ。マネージャーやオーナーは誰のものでも外せます。チェックは名前の付いた記録だからです。",
  "training.lessons.staff-checklists.step5": "チェックリストで作業するのに許可は決して要りません。テンプレートを作り、誰に割り当てるかを選ぶのはオーナーの仕事、またはオーナーがチェックリストテンプレートのチェックを与えた人の仕事です。",
