  "foodSafety.mock.title": "模擬検査",
  "foodSafety.mock.subtitle": "検査官が来る前に、検査官のように厨房を歩いてみましょう。",
  "foodSafety.mock.intro": "模擬検査を始めて、チェックしながらチェックリストのページで各項目に印を付けてください。各印には誰がいつチェックしたかが記録されます — 見つけたことはその場で直し、ファイルがその作業を示します。",
  "foodSafety.mock.startButton": "今日の模擬検査を始める",
  "foodSafety.mock.startFailed": "模擬検査は開始できませんでした。",
  "foodSafety.mock.startedNote": "あなたの模擬検査は今日のチェックリストにあります。",
  "foodSafety.mock.openChecklists": "チェックリストを開く",
  "foodSafety.mock.item1": "冷蔵庫、冷凍庫、保温が安全範囲内にあり、温度ログが記入されている。",
  "foodSafety.mock.item2": "冷却と再加熱のチェックが記録され、測定値が外れた箇所には是正措置がある。",
  "foodSafety.mock.item3": "消毒液が正しい濃度に混ぜられ、そのチェックが記録されている。",
  "foodSafety.mock.item4": "すべての食品証明書が有効で、まもなく期限切れになるものの更新が進んでいる。",
  "foodSafety.mock.item5": "安全データシートが、チーム全員が読める棚にある。",
  "foodSafety.mock.item6": "日付のある食品にラベルが付けられ、期限の早い順に使われている：一番早く切れるものが先。",
  "foodSafety.mock.item7": "すべての料理にアレルゲンマトリックスでアレルゲンが表示されている。",
  "foodSafety.mock.item8": "廃棄物ログが最新で、捨てたものすべてに理由がある。",
  "training.lessons.staff-food-safety.title": "食品安全ファイルを保つ",
  "training.lessons.staff-food-safety.step1": "食品安全ファイルはレストランコーナーの食品安全の棚にあります：温度ログ、冷却・再加熱・消毒剤ログ、証明書、安全データシート、検査パケット。",
  "training.lessons.staff-food-safety.step2": "範囲外の測定値は、そのメモが何をしたか — 再び冷やした、再加熱した、消毒剤を作り直した、捨てた — を言うまで完了ではありません。メモがなければ保存もなし：その記録は成り立ちません。",
  "training.lessons.staff-food-safety.step3": "冷却、再加熱、消毒剤のチェックは温度と同じように記録してください：何をチェックしたか、測定値、外れたときの是正措置。",
  "training.lessons.staff-food-safety.step4": "証明書は期限前に警告します。あなたの証明書が警告したら、オーナーに伝えてください — そして安全データシートは誰でもいつでも棚で読めます。",
  "training.lessons.staff-food-safety.step5": "検査の前 — またはいつでも — 食品安全の棚から模擬検査を実行し、検査官の日付で検査対応パケットを印刷してください。",
