  "training.lessons.staff-equipment.title": "設備記録と故障の報告",
  "training.lessons.staff-equipment.step1": "事業の各機械には設備の中に専用ページがあります：いつ買ったか、保証はいつまでか、誰が整備するか、そして起きたことすべて。",
  "training.lessons.staff-equipment.step2": "何か壊れたら、その機械自体で報告してください。何が壊れたかを書き、できれば問題の写真を追加してください — 報告はあなたの名前と時刻とともに機械の履歴に入ります。",
  "training.lessons.staff-equipment.step3": "故障を報告できるのは、オーナーから故障報告チェックをもらった場合だけです。ボタンがなければ、オーナーかマネージャーに伝えてください。ドアを開けてくれます。",
  "training.lessons.staff-equipment.step4": "保守作業 — 清掃、スケール除去、整備 — には期限があります。設備ページは期限のものと期限切れのものを表示し、何も静かに過ぎないようにします。",
  "training.lessons.staff-equipment.step5": "修理とその費用はオーナーかマネージャーが記録します。あなたの報告に対して修理が記録されると、故障は機械の履歴に修理済みと表示されます。",
