  "training.lessons.owner-tip-pooling.title": "チッププールとチップ記録",
  "training.lessons.owner-tip-pooling.step1": "レストラン、次にチーム＆場所、次にチッププールを開きます。プールの設定、分け前、記録を見ることができるのはオーナーだけです。",
  "training.lessons.owner-tip-pooling.step2": "プールの分け方を選びます：時間、役割のパーセンテージ、またはポイント。アプリは、すでに入っているスケジュールと打刻時間から分けます。",
  "training.lessons.owner-tip-pooling.step3": "期間を選び、プールの金額を入力し、分割をプレビューして、保存します。保存した分け前は、その期間の給与プレビューに入ります。",
  "training.lessons.owner-tip-pooling.step4": "準備ができたら保存した分割を公開します — チームメンバーはそのとき自分の分け前だけを見て、公開前には何も見ません。",
  "training.lessons.owner-tip-pooling.step5": "チップ記録をその都度残しましょう：1人ごと、期間ごと、報告されたチップ — そして年次記録は8%の計算をフォーム用の合計に換算します。アプリは記録を残すだけであり、何も提出しません。",
